//! Adapter P32: protocol, schema, capability, and locality integrity for gateways.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;
pub const CONTENT_TYPE:&str="application/vnd.aurora.adapter.gateway-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct GatewayEndpoint4{pub endpoint_id:String,pub protocol:String,pub schema:String,pub capability:String,pub version:String,pub checksum:String,pub evidence_state:String,pub approved:bool,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct GatewayIntegrityRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub endpoints:Vec<GatewayEndpoint4>,pub required_endpoint_order:Vec<String>,pub required_protocol_order:Vec<String>,pub replay_identity:String,pub policy_allowed:bool,pub protected_closure:bool,pub signed_manifest:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub adversarial_events:Vec<String>,pub endpoint_budget:usize,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct GatewayIntegrityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct GatewayIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub disposition:String,pub endpoint_order:Vec<String>,pub accepted_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub protocol_order:Vec<String>,pub schema_order:Vec<String>,pub capability_order:Vec<String>,pub version_order:Vec<String>,pub replay_identity:String,pub closure_digest:String,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:GatewayIntegrityArtifact4}
#[derive(Debug,Error)] pub enum GatewayIntegrityError{#[error("gateway integrity input is invalid: {0}")] Invalid(String),#[error("gateway integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())}
fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}
fn invalid(v:impl Into<String>)->GatewayIntegrityError{GatewayIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"adapter","consumers":["protocol gateway","schema registry","workflow compiler","research workbench"],"behavior":format!("qualify gateway compatibility at {scale} ({mode})"),"value":"prevents incompatible protocols, unapproved capabilities, and non-local data routes from entering research workflows","input_schema":"GatewayIntegrityRequest4@1","output_schema":"GatewayIntegrityCard7@1","effects":["emit:gateway-card","retain:compatibility-witness","block:unsafe-gateway"],"permissions":["read:local-capability-manifest"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
fn validate_card(c:&GatewayIntegrityCard7)->Result<(),GatewayIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.request_id.is_empty()||c.purpose.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest{return Err(invalid("gateway identity, locality, artifact, digest, or boundary is incomplete"));}for v in [&c.endpoint_order,&c.accepted_order,&c.rejected_order,&c.unknown_order,&c.omitted_order,&c.protocol_order,&c.schema_order,&c.capability_order,&c.version_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("gateway vectors are not canonical"));}}let ids=c.endpoint_order.iter().collect::<BTreeSet<_>>();let states=c.accepted_order.iter().chain(&c.rejected_order).chain(&c.unknown_order).chain(&c.omitted_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("endpoint states do not partition endpoints"));}Ok(())}
pub fn qualify(q:&GatewayIntegrityRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<GatewayIntegrityCard7,GatewayIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.endpoints.is_empty()||q.required_endpoint_order.is_empty()||!canonical(&q.required_endpoint_order)||!canonical(&q.required_protocol_order)||!digest(&q.replay_identity)||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.endpoint_budget==0{return Err(invalid("gateway identity, ordering, digest, locality, boundary, or budget is invalid"));}let mut rows=q.endpoints.clone();rows.sort_by(|a,b|a.endpoint_id.cmp(&b.endpoint_id));let mut seen=BTreeSet::new();let mut accepted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut protocols=BTreeSet::new();let mut schemas=BTreeSet::new();let mut capabilities=BTreeSet::new();let mut versions=BTreeSet::new();let mut evidence=BTreeSet::new();for e in &rows{if e.endpoint_id.trim().is_empty()||!seen.insert(e.endpoint_id.clone())||e.protocol.trim().is_empty()||e.schema.trim().is_empty()||e.capability.trim().is_empty()||e.version.trim().is_empty()||!digest(&e.checksum)||e.evidence_state.trim().is_empty()||!e.local||!e.aggregate_only{return Err(invalid("endpoint identity, protocol, schema, capability, version, evidence, digest, or locality is invalid"));}protocols.insert(format!("{}:{}",e.endpoint_id,e.protocol));schemas.insert(format!("{}:{}",e.endpoint_id,e.schema));capabilities.insert(format!("{}:{}",e.endpoint_id,e.capability));versions.insert(format!("{}:{}",e.endpoint_id,e.version));evidence.insert(e.checksum.clone());if e.evidence_state=="unknown"||e.checksum==q.replay_identity{unknown.insert(e.endpoint_id.clone());}else if !e.approved||e.protocol=="unknown"||e.schema=="unknown"{rejected.insert(e.endpoint_id.clone());}else if !q.required_endpoint_order.contains(&e.endpoint_id){omitted.insert(e.endpoint_id.clone());}else{accepted.insert(e.endpoint_id.clone());}}let missing=q.required_endpoint_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let global=!q.policy_allowed||!q.protected_closure||!q.signed_manifest||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty()||rows.len()>q.endpoint_budget;if global{omitted.extend(seen.iter().cloned());accepted.clear();rejected.clear();unknown.clear();}let disposition=if global{"blocked"}else if !missing.is_empty()||!unknown.is_empty(){"unknown"}else if !rejected.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let endpoint_order=seen.iter().cloned().collect::<Vec<_>>();let accepted_order=accepted.into_iter().collect::<Vec<_>>();let rejected_order=rejected.into_iter().collect::<Vec<_>>();let unknown_order=unknown.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"disposition":disposition,"endpoint_order":endpoint_order,"accepted_order":accepted_order,"rejected_order":rejected_order,"unknown_order":unknown_order,"omitted_order":omitted_order,"protocol_order":protocols.into_iter().collect::<Vec<_>>(),"schema_order":schemas.into_iter().collect::<Vec<_>>(),"capability_order":capabilities.into_iter().collect::<Vec<_>>(),"version_order":versions.into_iter().collect::<Vec<_>>(),"replay_identity":q.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let closure_digest=ContentHash::of_value(&body).map_err(|e|GatewayIntegrityError::Digest(e.to_string()))?.to_string();let effect_receipts=if disposition=="qualified"{vec![format!("approve:gateway:{}",q.request_id)]}else{vec!["block:unsafe-gateway".into()]};let artifact=GatewayIntegrityArtifact4{artifact_id:format!("adapter-gateway:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:body["omitted_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=GatewayIntegrityCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),disposition:disposition.into(),endpoint_order:body["endpoint_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),accepted_order,rejected_order,unknown_order,omitted_order,protocol_order:body["protocol_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),schema_order:body["schema_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),capability_order:body["capability_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),version_order:body["version_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),replay_identity:q.replay_identity.clone(),closure_digest,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts,artifact};let _=(scale,mode);validate_card(&c)?;Ok(c)}
